-- Adopt rbac
--
-- PLAT-01a: membership and RBAC foundation. No product-table policy changes here (those are PLAT-01c to 01e).
-- Storage as generated by @geiger/rbac migrationSql("property") at 1835de3, minus its open policies and anon grants.
-- Shared (kept on rollback): public.roles, public.rbac_key_matches(text[], text), public.rbac_touch_updated_at().
-- Owns: property.role_grants with its policies and trigger, property.rbac_allows(text, uuid, text, uuid),
--   property.can_access_project(uuid), property.member_project_ids(), property.rbac_owner_role(uuid),
--   property.rbac_ensure_membership(uuid), property.rbac_migrate_key(text), property.rbac_check_grant_project(),
--   and the property_roles_write policy on public.roles.
-- Backfill: settings key `roles` becomes public.roles rows (keys via rbac_migrate_key, merged into a shared role of the
--   same key), and team_members whose email matches an account get metadata.userId plus a grant of their role.
-- @down drops what this file owns; backfilled public.roles rows and team_members.metadata.userId stay.

-- @up
create extension if not exists pgcrypto;
create schema if not exists property;
grant usage on schema property to anon, authenticated, service_role;

-- Shared updated_at trigger for the authorization tables; declared by whichever product adopts first.
create or replace function public.rbac_touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

-- Wildcard permission matching, mirroring @geiger/rbac keys.js ("*", "<product>.*", "<product>.<resource>.*").
create or replace function public.rbac_key_matches(p_patterns text[], p_key text)
returns boolean
language sql
immutable
as $$
  select exists (
    select 1
    from unnest(coalesce(p_patterns, '{}'::text[])) as pat
    where pat = '*'
       or pat = p_key
       or (
         right(pat, 2) = '.*'
         and left(p_key, length(pat) - 1) = left(pat, length(pat) - 1)
       )
  );
$$;

-- Shared role definitions; a role's permissions[] spans every product, a null project_id is a suite-wide template.
create table if not exists public.roles (
  id uuid primary key default gen_random_uuid(),
  project_id uuid references public.projects(id) on delete cascade,
  key text,
  name text not null default 'Untitled role',
  description text not null default '',
  color text not null default 'slate',
  permissions text[] not null default '{}',
  is_system boolean not null default false,
  sort integer not null default 0,
  metadata jsonb not null default '{}'::jsonb,
  created_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);

alter table public.roles add column if not exists key text;
alter table public.roles add column if not exists permissions text[] not null default '{}';
alter table public.roles add column if not exists metadata jsonb not null default '{}'::jsonb;
alter table public.roles add column if not exists deleted_at timestamptz;

create index if not exists roles_project_idx
  on public.roles (project_id) where deleted_at is null;
create unique index if not exists roles_project_key_uniq
  on public.roles (project_id, key) where key is not null and deleted_at is null;

drop trigger if exists roles_touch_updated_at on public.roles;
create trigger roles_touch_updated_at
before update on public.roles
for each row execute function public.rbac_touch_updated_at();

-- Property's assignments: one row per (user, role) in a project; scope narrows a grant ({} applies everywhere).
create table if not exists property.role_grants (
  id uuid primary key default gen_random_uuid(),
  project_id uuid references public.projects(id) on delete cascade,
  user_id uuid not null,
  role_id uuid not null references public.roles(id) on delete cascade,
  scope jsonb not null default '{}'::jsonb,
  status text not null default 'active',
  metadata jsonb not null default '{}'::jsonb,
  granted_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);

alter table property.role_grants add column if not exists scope jsonb not null default '{}'::jsonb;
alter table property.role_grants add column if not exists metadata jsonb not null default '{}'::jsonb;
alter table property.role_grants add column if not exists deleted_at timestamptz;

-- The lookup rbac_allows() makes on every gated row.
create index if not exists property_role_grants_lookup_idx
  on property.role_grants (user_id, project_id) where deleted_at is null;
create index if not exists property_role_grants_role_idx
  on property.role_grants (role_id) where deleted_at is null;
create unique index if not exists property_role_grants_uniq
  on property.role_grants (project_id, user_id, role_id) where deleted_at is null;

drop trigger if exists role_grants_touch_updated_at on property.role_grants;
create trigger role_grants_touch_updated_at
before update on property.role_grants
for each row execute function public.rbac_touch_updated_at();

grant execute on function public.rbac_key_matches(text[], text) to anon, authenticated;

-- A grant's role must belong to the grant's project; the shared FK only checks the role id.
create or replace function property.rbac_check_grant_project()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.project_id is null or not exists (
    select 1 from public.roles r where r.id = new.role_id and r.project_id = new.project_id
  ) then
    raise exception 'Role grant project mismatch' using errcode = '23503';
  end if;
  return new;
end;
$$;
revoke all on function property.rbac_check_grant_project() from public, anon, authenticated;

drop trigger if exists role_grants_check_project on property.role_grants;
create trigger role_grants_check_project
before insert or update of project_id, role_id on property.role_grants
for each row execute function property.rbac_check_grant_project();

-- Project access is dash's org membership; never re-implement it here.
create or replace function property.can_access_project(p_project_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select public.is_project_member(p_project_id);
$$;
revoke all on function property.can_access_project(uuid) from public, anon;
grant execute on function property.can_access_project(uuid) to authenticated, service_role;

-- The caller's projects, for `project_id in (select property.member_project_ids())` (evaluated once per statement).
create or replace function property.member_project_ids()
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select p.id from public.projects p where p.deleted_at is null and public.is_project_member(p.id);
$$;
revoke all on function property.member_project_ids() from public, anon;
grant execute on function property.member_project_ids() to authenticated, service_role;

-- The predicate gated policies and server routes call: an active grant, in a project the caller can still reach,
-- whose role (from the same project) matches the key, within scope. Hardened as content's project_scoped_rls.
create or replace function property.rbac_allows(
  p_permission text,
  p_project uuid default null,
  p_scope_type text default null,
  p_scope_id uuid default null
)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select auth.uid() is not null and exists (
    select 1
      from property.role_grants g
      join public.roles r on r.id = g.role_id and r.project_id = g.project_id
     where g.user_id = auth.uid()
       and g.status = 'active'
       and g.deleted_at is null
       and r.deleted_at is null
       and (p_project is null or g.project_id = p_project)
       and property.can_access_project(g.project_id)
       and public.rbac_key_matches(r.permissions, p_permission)
       and (
         p_scope_type is null
         or not jsonb_exists(g.scope, p_scope_type)
         or (p_scope_id is not null and jsonb_exists(g.scope -> p_scope_type, p_scope_id::text))
       )
  );
$$;
revoke all on function property.rbac_allows(text, uuid, text, uuid) from public, anon;
grant execute on function property.rbac_allows(text, uuid, text, uuid) to authenticated, service_role;

-- The project's Owner role ("*"), seeded when missing; internal to this file's functions.
create or replace function property.rbac_owner_role(p_project uuid)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_role uuid;
begin
  select r.id into v_role from public.roles r
   where r.project_id = p_project and r.key = 'owner' and r.deleted_at is null
   limit 1;
  if v_role is null then
    insert into public.roles (project_id, key, name, description, color, permissions, is_system, sort, metadata)
    values (p_project, 'owner', 'Owner', 'Full access to everything, including billing.', 'violet', array['*'], true, 0,
            jsonb_build_object('key', 'owner'))
    on conflict (project_id, key) where key is not null and deleted_at is null do nothing
    returning id into v_role;
  end if;
  if v_role is null then
    select r.id into v_role from public.roles r
     where r.project_id = p_project and r.key = 'owner' and r.deleted_at is null
     limit 1;
  end if;
  return v_role;
end;
$$;
revoke all on function property.rbac_owner_role(uuid) from public, anon, authenticated;

-- One-shot translation of pre-01a settings keys to catalog keys; mirrors toPermissionKey() in lib/rbac.js.
create or replace function property.rbac_migrate_key(p_key text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case
    when p_key = '*' then '*'
    when p_key = 'team.invite' then 'property.team.invite'
    when p_key = 'team.assign_roles' then 'property.team.assign'
    when p_key = 'roles.manage' then 'property.role.manage'
    when p_key = 'billing.manage' then 'property.billing.manage'
    when p_key = 'settings.manage' then 'property.settings.manage'
    when p_key = 'records.delete' then 'property.record.delete'
    when p_key = 'accounting.post' then 'property.accounting.post'
    when p_key = 'accounting.void' then 'property.accounting.void'
    when p_key = 'reports.export' then 'property.report.export'
    when p_key = 'reports.schedule' then 'property.report.schedule'
    when p_key = 'review.resolve' then 'property.review.resolve'
    when p_key = 'automations.manage' then 'property.automation.manage'
    when p_key = 'automations.run' then 'property.automation.run'
    when p_key ~ '^view\.[a-z0-9_]+$' then
      'property.' || case when substr(p_key, 6, 1) ~ '[0-9]' then 'page_' else '' end || substr(p_key, 6) || '.view'
    else null
  end;
$$;
revoke all on function property.rbac_migrate_key(text) from public, anon, authenticated;
grant execute on function property.rbac_migrate_key(text) to service_role;

-- The caller's own grant in a project, minted on first load. Precedence: an existing grant; nothing after a revoked
-- or deactivated grant or a disabled roster row; Owner for the org owner (or an org-less project's creator); the
-- role their roster row names (never owner-grade); the shared Admin role for org admins once it carries Property
-- permissions; else Manager. Claims the matching roster row (metadata.userId, Invited → Active).
create or replace function property.rbac_ensure_membership(p_project uuid)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_email text;
  v_org_role text;
  v_member property.team_members%rowtype;
  v_wanted text;
  v_role uuid;
begin
  if p_project is null or v_uid is null or not property.can_access_project(p_project) then
    return null;
  end if;
  perform pg_advisory_xact_lock(hashtext('property-membership:' || p_project::text || ':' || v_uid::text)::bigint);

  select lower(coalesce(u.email, '')) into v_email from auth.users u where u.id = v_uid;

  -- Their roster row: already linked, else an unclaimed one addressed to their email.
  select tm.* into v_member
    from property.team_members tm
   where tm.project_id = p_project
     and tm.deleted_at is null
     and (tm.metadata ->> 'userId' = v_uid::text
          or (v_email <> '' and lower(tm.email) = v_email and not (tm.metadata ? 'userId')))
   order by (tm.metadata ->> 'userId' = v_uid::text) desc nulls last, tm.created_at
   limit 1;
  if v_member.id is not null and not (v_member.metadata ? 'userId') then
    update property.team_members set metadata = metadata || jsonb_build_object('userId', v_uid) where id = v_member.id;
  end if;

  select g.role_id into v_role
    from property.role_grants g
   where g.project_id = p_project and g.user_id = v_uid and g.status = 'active' and g.deleted_at is null
   limit 1;
  if v_role is not null then
    return v_role;
  end if;

  if v_member.status = 'Disabled'
     or exists (select 1 from property.role_grants g where g.project_id = p_project and g.user_id = v_uid) then
    return null;
  end if;

  select lower(ou.role::text) into v_org_role
    from public.projects p
    join public.organization_users ou on ou.organization = p.organization_id and ou."user" = v_uid
   where p.id = p_project
   limit 1;

  if v_org_role = 'owner' or public.is_verified_project_owner(p_project) then
    v_role := property.rbac_owner_role(p_project);
  end if;

  if v_role is null and coalesce(v_member.role, '') <> '' then
    v_wanted := trim(both '_' from regexp_replace(lower(v_member.role), '[^a-z0-9]+', '_', 'g'));
    select r.id into v_role
      from public.roles r
     where r.project_id = p_project
       and r.deleted_at is null
       and (r.key = v_wanted or lower(r.name) = lower(trim(v_member.role)))
       and not exists (select 1 from unnest(r.permissions) k where k = '*' or k like '%.*')
     order by (r.key = v_wanted) desc nulls last
     limit 1;
  end if;

  if v_role is null and v_org_role = 'admin' then
    select r.id into v_role
      from public.roles r
     where r.project_id = p_project and r.key = 'admin' and r.deleted_at is null
       and exists (select 1 from unnest(r.permissions) k where k = '*' or k like 'property.%')
     limit 1;
  end if;

  if v_role is null then
    select r.id into v_role
      from public.roles r
     where r.project_id = p_project and r.key = 'manager' and r.deleted_at is null
     limit 1;
  end if;

  if v_role is null then
    return null;
  end if;

  insert into property.role_grants (project_id, user_id, role_id, status, metadata)
  values (p_project, v_uid, v_role, 'active', jsonb_build_object('source', 'membership'))
  on conflict do nothing;

  if v_member.status = 'Invited' then
    update property.team_members set status = 'Active' where id = v_member.id;
  end if;
  return v_role;
end;
$$;
revoke all on function property.rbac_ensure_membership(uuid) from public, anon;
grant execute on function property.rbac_ensure_membership(uuid) to authenticated;

-- Grants: members read their project's grants; writes need property.team.assign and, as events' role write guards
-- do, a project role administrator (org owner/admin, or an org-less project's creator). Soft delete only.
alter table property.role_grants enable row level security;
revoke all on property.role_grants from public, anon, authenticated;
grant select, insert, update on property.role_grants to authenticated;
grant all on property.role_grants to service_role;

drop policy if exists role_grants_read on property.role_grants;
drop policy if exists role_grants_write on property.role_grants;

drop policy if exists role_grants_member_select on property.role_grants;
create policy role_grants_member_select on property.role_grants
  for select to authenticated
  using (project_id in (select property.member_project_ids()));

drop policy if exists role_grants_assign_insert on property.role_grants;
create policy role_grants_assign_insert on property.role_grants
  for insert to authenticated
  with check (property.rbac_allows('property.team.assign', project_id));

drop policy if exists role_grants_assign_update on property.role_grants;
create policy role_grants_assign_update on property.role_grants
  for update to authenticated
  using (property.rbac_allows('property.team.assign', project_id))
  with check (property.rbac_allows('property.team.assign', project_id));

drop policy if exists role_grants_admin_insert_guard on property.role_grants;
create policy role_grants_admin_insert_guard on property.role_grants
  as restrictive for insert to authenticated
  with check (public.can_administer_project_roles(project_id));

drop policy if exists role_grants_admin_update_guard on property.role_grants;
create policy role_grants_admin_update_guard on property.role_grants
  as restrictive for update to authenticated
  using (public.can_administer_project_roles(project_id))
  with check (public.can_administer_project_roles(project_id));

-- Property's own way into the shared roles table, shaped like dash's per-product policies (harden_org_and_roles_rls);
-- the suite's restrictive role guards still apply on top.
drop policy if exists property_roles_write on public.roles;
create policy property_roles_write on public.roles
  for all to authenticated
  using (
    public.can_administer_project_roles(project_id)
    or (
      public.is_project_member(project_id)
      and property.rbac_allows('property.role.manage', project_id)
      and not ('*' = any (permissions))
    )
  )
  with check (
    public.can_administer_project_roles(project_id)
    or (
      public.is_project_member(project_id)
      and property.rbac_allows('property.role.manage', project_id)
      and not ('*' = any (permissions))
    )
  );

-- Backfill 1: settings `roles` → public.roles. Old Owner becomes the "*" role; other keys translate, merging into a
-- shared role of the same key; `known` becomes metadata.propertyKnown so the app's catalog top-up honours decisions.
do $backfill$
declare
  s record;
  r jsonb;
  v_ord integer;
  v_key text;
  v_perms text[];
  v_known text[];
  v_known_meta jsonb;
  v_role uuid;
begin
  for s in
    select st.project_id, st.value
      from property.settings st
      join public.projects p on p.id = st.project_id and p.deleted_at is null
     where st.key = 'roles' and st.deleted_at is null and jsonb_typeof(st.value) = 'array'
  loop
    v_ord := 0;
    for r in select e.value from jsonb_array_elements(s.value) e loop
      v_ord := v_ord + 1;
      v_key := trim(both '_' from regexp_replace(lower(coalesce(r ->> 'id', r ->> 'name', '')), '[^a-z0-9]+', '_', 'g'));
      continue when v_key = '';
      if v_key = 'owner' then
        perform property.rbac_owner_role(s.project_id);
        continue;
      end if;
      v_perms := array(
        select distinct t.k from (
          select property.rbac_migrate_key(x) as k
            from jsonb_array_elements_text(case when jsonb_typeof(r -> 'permissions') = 'array' then r -> 'permissions' else '[]'::jsonb end) x
        ) t
        where t.k is not null and t.k <> '*'
      );
      v_known := case when jsonb_typeof(r -> 'known') = 'array' then array(
        select distinct t.k from (select property.rbac_migrate_key(x) as k from jsonb_array_elements_text(r -> 'known') x) t
        where t.k is not null and t.k <> '*'
      ) end;
      v_known_meta := case when v_known is null then '{}'::jsonb else jsonb_build_object('propertyKnown', to_jsonb(v_known)) end;
      select id into v_role from public.roles where project_id = s.project_id and key = v_key and deleted_at is null limit 1;
      if v_role is null then
        insert into public.roles (project_id, key, name, permissions, is_system, sort, metadata)
        values (s.project_id, v_key, coalesce(nullif(trim(r ->> 'name'), ''), v_key), v_perms,
                v_key in ('manager', 'leasing_agent', 'maintenance_tech', 'accountant'), 10 + v_ord,
                jsonb_build_object('key', v_key) || v_known_meta);
      else
        update public.roles
           set permissions = array(select distinct unnest(permissions || v_perms)),
               metadata = metadata || v_known_meta
         where id = v_role;
      end if;
    end loop;
  end loop;
end;
$backfill$;

-- Backfill 2: link roster rows to accounts by email, then grant each linked member the role their row names (by key,
-- then name; never owner-grade). Disabled rows get an inactive grant so access isn't handed back on first load.
update property.team_members tm
   set metadata = tm.metadata || jsonb_build_object('userId', u.id)
  from auth.users u, public.projects p
 where p.id = tm.project_id
   and p.deleted_at is null
   and tm.deleted_at is null
   and coalesce(tm.email, '') <> ''
   and lower(u.email) = lower(tm.email)
   and not (tm.metadata ? 'userId');

insert into property.role_grants (project_id, user_id, role_id, status, metadata)
select distinct on (tm.project_id, u.id)
       tm.project_id, u.id, r.id,
       case when tm.status = 'Disabled' then 'inactive' else 'active' end,
       jsonb_build_object('source', 'team_members')
  from property.team_members tm
  join auth.users u on u.id::text = tm.metadata ->> 'userId'
  join public.roles r
    on r.project_id = tm.project_id
   and r.deleted_at is null
   and (r.key = trim(both '_' from regexp_replace(lower(tm.role), '[^a-z0-9]+', '_', 'g')) or lower(r.name) = lower(trim(tm.role)))
   and not exists (select 1 from unnest(r.permissions) k where k = '*' or k like '%.*')
 where tm.deleted_at is null
   and coalesce(tm.role, '') <> ''
 order by tm.project_id, u.id, (r.key = trim(both '_' from regexp_replace(lower(tm.role), '[^a-z0-9]+', '_', 'g'))) desc, tm.created_at
on conflict (project_id, user_id, role_id) where deleted_at is null do nothing;

-- @down
drop policy if exists property_roles_write on public.roles;
drop function if exists property.rbac_ensure_membership(uuid);
drop function if exists property.rbac_migrate_key(text);
drop function if exists property.rbac_owner_role(uuid);
drop table if exists property.role_grants cascade;
drop function if exists property.rbac_check_grant_project();
drop function if exists property.rbac_allows(text, uuid, text, uuid);
drop function if exists property.member_project_ids();
drop function if exists property.can_access_project(uuid);

-- public.roles, public.rbac_key_matches and public.rbac_touch_updated_at are shared across the suite and stay, as do
-- the backfilled public.roles rows and team_members.metadata.userId links.
